mapper.select:
SELECT d.name AS "name", d.code AS "modelCode",
       c.code AS "capability", p.path AS "islandPath"
  FROM device d
  LEFT JOIN capability c ON c.id = d.capability_id
  LEFT JOIN resource_node p ON p.id = #{param3}
 WHERE d.tenant_id = #{param1} AND d.id = #{param2}

mapper.update:
UPDATE device SET capability_id = #{param3}
 WHERE tenant_id = #{param1}
   AND id = (SELECT device_model_id FROM device_instance
              WHERE tenant_id = #{param1} AND resource_id = #{param2})

UPDATE device SET attr = COALESCE(attr, '{}'::jsonb) || #{patch}::jsonb,
                  updated_at = now()
 WHERE tenant_id = #{t} AND id = #{deviceId}

mapper.select:
SELECT id FROM device_instance
 WHERE tenant_id = #{param1} AND resource_id = #{param2}
 ORDER BY id LIMIT 1

mapper.delete:
DELETE FROM node_binding
 WHERE tenant_id = #{param1}
   AND (device_instance_id = #{param3}
        OR position_id IN (SELECT id FROM device_point
                            WHERE tenant_id = #{param1} AND device_resource_id = #{param2}))

mapper.select:
SELECT code FROM resource_node
 WHERE tenant_id = #{param1} AND id = #{param2}
   AND kind = #{param3}::resource_kind

mapper.update:
UPDATE device_method SET interruptible = #{param4}, updated_at = now()
 WHERE tenant_id = #{param1} AND device_model_id = #{param2}
   AND method = #{param3} AND scope = 'model'

mapper.select:
SELECT EXISTS (SELECT 1 FROM driver
               WHERE tenant_id = #{tenantId} AND code = #{code}
                 AND deleted_at IS NULL)

mapper.update:
UPDATE robot_point SET updated_at = now(), synced_at = now()
, x = #{x}
, y = #{y}
, z = #{z}
, device_resource_id = #{deviceResourceId}
, action = #{action}
 WHERE tenant_id = #{tenantId} AND island_id = #{islandId} AND code = #{code}
